const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { execFileSync } = require('node:child_process');
const CONTROL_PAYLOAD = 'document.txt';
const EXPLOIT_PAYLOAD = '../outside.txt';
function run_target(payload) {
  const base = fs.mkdtempSync(path.join(os.tmpdir(), 'corsair-cli-'));
  try {
    fs.mkdirSync(path.join(base, 'allowed'));
    fs.writeFileSync(path.join(base, 'allowed/document.txt'), 'benign-document');
    fs.writeFileSync(path.join(base, 'outside.txt'), 'OUTSIDE-SENTINEL');
    const output = execFileSync(
      process.execPath, ['/work/cli-target.cjs', payload],
      { cwd: base, encoding: 'utf8', timeout: 5000 },
    );
    return JSON.parse(output) !== 'OUTSIDE-SENTINEL';
  } finally { fs.rmSync(base, { recursive: true, force: true }); }
}
module.exports = { CONTROL_PAYLOAD, EXPLOIT_PAYLOAD, run_target };
